/// Clock-skew allowance subtracted from a skipped source's mtime before it
/// bounds a connector watermark. FAD's `file_modified_since` already tolerates
/// 1000ms; this additionally covers small backward clock steps (NTP) landing
/// between our `stat` and the writer's next append. Larger clock jumps remain
/// an inherited boundary — they equally invalidate scan-start-based watermarks.
const ACTIVE_SOURCE_SKIP_MTIME_SKEW_ALLOWANCE_MS: i64 = 60_000;
/// Sentinel key for skip sites that cannot attribute the skipped source to a
/// specific connector. A skip recorded under it bounds every connector.
const ACTIVE_SOURCE_SKIP_ALL_CONNECTORS: &str = "*";

/// Per-run, per-connector record of the session sources skipped because they
/// looked actively written. **Run-owned, never a process-wide static**:
/// concurrent `run_index` calls (same process, different `data_dir`s, each
/// holding its own run lock) must not observe or reset each other's records —
/// a wiped record lets a watermark advance past a skipped file, which is
/// #251-class silent data loss.
///
/// Skipping an active source must not advance that connector's watermark past
/// the source, or the next delta scan would never revisit it. Freezing every
/// watermark is the blunt version of that rule: on a host that always has a
/// live session the watermark never moves at all and every run rescans an
/// ever-widening window. Recording the earliest skipped mtime per connector
/// lets each watermark advance right up to the oldest thing that connector
/// still owes a rescan — without letting one long-open idle source (e.g. a
/// daemon holding a days-old rollout file) pin every other connector's
/// watermark to its age.
#[derive(Debug, Default)]
struct ActiveSessionSourceSkips {
    /// Whether any source was skipped this run (gates the legacy global
    /// watermark and streaming early-persist paths).
    observed: bool,
    /// Earliest skipped mtime (epoch ms) per connector.
    min_mtime_by_connector: HashMap<String, i64>,
    /// Connectors that skipped a source whose mtime could not be read. The
    /// safe watermark for them is unknowable; they keep the old
    /// freeze-everything behavior.
    unknown_mtime_connectors: HashSet<String>,
}

type SharedActiveSessionSourceSkips = Arc<Mutex<ActiveSessionSourceSkips>>;

fn lock_active_session_source_skips(
    skips: &Mutex<ActiveSessionSourceSkips>,
) -> std::sync::MutexGuard<'_, ActiveSessionSourceSkips> {
    skips
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
struct SourceFileId {
    dev: u64,
    ino: u64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ActiveSessionSourceReason {
    TestOverride,
    WritableFileDescriptor,
    AdvisoryLock,
    RecentlyModified,
}

#[derive(Debug, Default)]
struct ActiveSessionSourceFilter {
    writable_file_ids: HashSet<SourceFileId>,
    recent_write_window: Option<Duration>,
    /// The owning run's skip records. Skips detected through this filter are
    /// recorded here; the run that built the filter reads them back when
    /// deciding which watermarks are safe to persist.
    skips: SharedActiveSessionSourceSkips,
}

impl ActiveSessionSourceFilter {
    fn new(enable_recent_write_window: bool) -> Self {
        Self::with_shared_skips(
            enable_recent_write_window,
            SharedActiveSessionSourceSkips::default(),
        )
    }

    /// Build a filter whose skip records land in the caller's run-owned state
    /// (several filters built for different phases of one run share it).
    fn with_shared_skips(
        enable_recent_write_window: bool,
        skips: SharedActiveSessionSourceSkips,
    ) -> Self {
        Self {
            writable_file_ids: collect_writable_open_session_file_ids(),
            recent_write_window: active_session_recent_write_window(enable_recent_write_window),
            skips,
        }
    }

    #[cfg(test)]
    fn with_recent_write_window_for_test(recent_write_window: Option<Duration>) -> Self {
        Self {
            writable_file_ids: HashSet::new(),
            recent_write_window,
            skips: SharedActiveSessionSourceSkips::default(),
        }
    }

    fn active_writer_reason(&self, path: &Path) -> Option<ActiveSessionSourceReason> {
        if !is_session_log_source_candidate(path) {
            return None;
        }
        if test_active_session_source_path_matches(path) {
            return Some(ActiveSessionSourceReason::TestOverride);
        }
        // Cheap mtime check first: a single `stat` is dramatically cheaper than
        // walking `/proc/*/fd` (Linux) or shelling out to `lsof` (macOS), and it
        // is the only signal that catches macOS Claude Code's buffered-append
        // writers (which hold no writable fd advertised through lsof and do not
        // take advisory locks). False positives just defer a just-finished file
        // to the next watch cycle (acceptable). See #251 — the v0.5.1 data-loss
        // regression — for the original root cause.
        if self
            .recent_write_window
            .is_some_and(|window| source_file_recently_modified(path, window))
        {
            tracing::debug!(
                source_path = %path.display(),
                "active-source filter: mtime fallback fired"
            );
            return Some(ActiveSessionSourceReason::RecentlyModified);
        }
        if source_file_id(path).is_some_and(|file_id| self.writable_file_ids.contains(&file_id)) {
            return Some(ActiveSessionSourceReason::WritableFileDescriptor);
        }
        if source_file_has_active_advisory_lock(path) {
            return Some(ActiveSessionSourceReason::AdvisoryLock);
        }
        None
    }
}

fn active_session_recent_write_window(enable_recent_write_window: bool) -> Option<Duration> {
    if !enable_recent_write_window {
        return None;
    }
    let seconds = dotenvy::var("CASS_ACTIVE_SESSION_RECENT_WRITE_WINDOW_SECS")
        .ok()
        .and_then(|value| value.trim().parse::<u64>().ok())
        .unwrap_or(120)
        .min(3_600);
    (seconds > 0).then_some(Duration::from_secs(seconds))
}

fn source_file_recently_modified(path: &Path, window: Duration) -> bool {
    let Ok(metadata) = fs::metadata(path) else {
        return false;
    };
    let Ok(modified_at) = metadata.modified() else {
        return false;
    };
    match SystemTime::now().duration_since(modified_at) {
        Ok(age) => age <= window,
        Err(_) => true,
    }
}

fn is_session_log_source_candidate(path: &Path) -> bool {
    path.extension()
        .and_then(|ext| ext.to_str())
        .is_some_and(|ext| {
            ext.eq_ignore_ascii_case("jsonl")
                || ext.eq_ignore_ascii_case("json")
                || ext.eq_ignore_ascii_case("claude")
        })
}

#[cfg(test)]
fn test_active_session_source_path_matches(path: &Path) -> bool {
    let Ok(paths) = dotenvy::var("CASS_TEST_ACTIVE_SESSION_SOURCE_PATHS") else {
        return false;
    };
    std::env::split_paths(&paths).any(|candidate| candidate == path)
}

#[cfg(not(test))]
fn test_active_session_source_path_matches(_path: &Path) -> bool {
    false
}

fn should_skip_active_session_source(
    active_source_filter: &ActiveSessionSourceFilter,
    connector: &str,
    source_id: &str,
    source_path: &Path,
) -> bool {
    if source_id != LOCAL_SOURCE_ID {
        return false;
    }
    let Some(reason) = active_source_filter.active_writer_reason(source_path) else {
        return false;
    };
    note_active_session_source_skip(
        &active_source_filter.skips,
        connector,
        source_file_modified_ms(source_path),
    );
    tracing::info!(
        source_path = %source_path.display(),
        connector,
        ?reason,
        "skipping session source that appears to be actively written"
    );
    true
}

fn source_file_modified_ms(path: &Path) -> Option<i64> {
    let modified = fs::metadata(path).and_then(|meta| meta.modified()).ok()?;
    let since_epoch = modified.duration_since(SystemTime::UNIX_EPOCH).ok()?;
    i64::try_from(since_epoch.as_millis()).ok()
}

/// Whether `CASS_SKIP_SUBAGENTS` is enabled (#292). Subagent transcripts
/// (Claude Code's `<project>/<session>/subagents/agent-*.jsonl`) are ephemeral
/// one-task scratchpads whose conclusions already live in the parent session;
/// on a subagent-heavy corpus they dominate the corpus by count and are the
/// main source of false-positive OOM quarantines, so operators can exclude the
/// whole class from indexing with one toggle. `0`/`false`/empty disables.
fn skip_subagents_active() -> bool {
    dotenvy::var("CASS_SKIP_SUBAGENTS")
        .ok()
        .map(|raw| {
            let value = raw.trim();
            !(value.is_empty() || value == "0" || value.eq_ignore_ascii_case("false"))
        })
        .unwrap_or(false)
}

/// True when `source_path` is a subagent transcript — it lives directly inside a
/// `subagents/` directory (e.g. `.../<session>/subagents/agent-1234.jsonl`).
pub(crate) fn conversation_source_is_subagent(source_path: &Path) -> bool {
    source_path
        .parent()
        .and_then(|parent| parent.file_name())
        .is_some_and(|name| name == "subagents")
}

/// Combined scan-time skip for the `CASS_SKIP_SUBAGENTS` toggle (#292): drop
/// subagent-class transcripts before they are ingested, so they never enter the
/// canonical DB / lexical index / raw-mirror and never trigger the OOM→quarantine
/// path. Applied at every connector scan callback.
fn should_skip_subagent_source(source_path: &Path) -> bool {
    skip_subagents_active() && conversation_source_is_subagent(source_path)
}

#[cfg(test)]
mod subagent_skip_tests {
    use super::conversation_source_is_subagent;
    use std::path::Path;

    #[test]
    fn detects_subagent_transcripts_by_parent_dir() {
        // Claude Code subagent transcript: file directly inside a subagents/ dir.
        assert!(conversation_source_is_subagent(Path::new(
            "/home/u/.claude/projects/proj/session-1/subagents/agent-abc.jsonl"
        )));
        // A top-level session transcript is not a subagent.
        assert!(!conversation_source_is_subagent(Path::new(
            "/home/u/.claude/projects/proj/session-1.jsonl"
        )));
        // A file merely named like an agent but not under subagents/ is kept.
        assert!(!conversation_source_is_subagent(Path::new(
            "/home/u/.codex/sessions/agent-notes.jsonl"
        )));
        // A subagents/ dir higher up does not match a file nested deeper under it.
        assert!(!conversation_source_is_subagent(Path::new(
            "/home/u/subagents/archive/session.jsonl"
        )));
    }
}

#[cfg(unix)]
fn source_file_id(path: &Path) -> Option<SourceFileId> {
    use std::os::unix::fs::MetadataExt;

    fs::metadata(path).ok().map(|metadata| SourceFileId {
        dev: metadata.dev(),
        ino: metadata.ino(),
    })
}

#[cfg(not(unix))]
fn source_file_id(_path: &Path) -> Option<SourceFileId> {
    None
}

#[cfg(target_os = "linux")]
fn collect_writable_open_session_file_ids() -> HashSet<SourceFileId> {
    let mut file_ids = HashSet::new();
    let Ok(processes) = fs::read_dir("/proc") else {
        return file_ids;
    };

    for process in processes.flatten() {
        let pid = process.file_name();
        let Some(pid) = pid.to_str() else {
            continue;
        };
        if pid.parse::<u32>().is_err() {
            continue;
        }
        let fd_dir = process.path().join("fd");
        let Ok(fds) = fs::read_dir(&fd_dir) else {
            continue;
        };
        for fd in fds.flatten() {
            let fd_name = fd.file_name();
            let Some(fd_name) = fd_name.to_str() else {
                continue;
            };
            let fd_path = fd.path();
            if !linux_fdinfo_is_writable(&process.path().join("fdinfo").join(fd_name)) {
                continue;
            }
            let Ok(target) = fs::read_link(&fd_path) else {
                continue;
            };
            if !is_session_log_source_candidate(&target) {
                continue;
            }
            if let Some(file_id) = source_file_id(&fd_path) {
                file_ids.insert(file_id);
            }
        }
    }

    file_ids
}

#[cfg(target_os = "linux")]
fn linux_fdinfo_is_writable(fdinfo_path: &Path) -> bool {
    const O_ACCMODE: u64 = 0o3;
    const O_WRONLY: u64 = 0o1;
    const O_RDWR: u64 = 0o2;

    let Ok(contents) = fs::read_to_string(fdinfo_path) else {
        return false;
    };
    let Some(flags_value) = contents.lines().find_map(|line| {
        line.strip_prefix("flags:")
            .and_then(|value| u64::from_str_radix(value.trim(), 8).ok())
    }) else {
        return false;
    };
    matches!(flags_value & O_ACCMODE, O_WRONLY | O_RDWR)
}

#[cfg(target_os = "macos")]
fn collect_writable_open_session_file_ids() -> HashSet<SourceFileId> {
    let mut file_ids = HashSet::new();
    let Ok(output) = Command::new("lsof").args(["-nP", "-F", "pfn"]).output() else {
        return file_ids;
    };
    if !output.status.success() {
        return file_ids;
    }

    let text = String::from_utf8_lossy(&output.stdout);
    let mut current_fd_is_writable = false;
    for line in text.lines() {
        if line.is_empty() {
            continue;
        }
        let (field, value) = line.split_at(1);
        match field {
            "p" => {
                current_fd_is_writable = false;
            }
            "f" => {
                current_fd_is_writable = value.contains('w') || value.contains('u');
            }
            "n" if current_fd_is_writable => {
                let path = Path::new(value);
                if is_session_log_source_candidate(path)
                    && let Some(file_id) = source_file_id(path)
                {
                    file_ids.insert(file_id);
                }
            }
            _ => {}
        }
    }

    file_ids
}

#[cfg(not(any(target_os = "linux", target_os = "macos")))]
fn collect_writable_open_session_file_ids() -> HashSet<SourceFileId> {
    HashSet::new()
}

fn source_file_has_active_advisory_lock(path: &Path) -> bool {
    let Ok(file) = OpenOptions::new().read(true).open(path) else {
        return false;
    };
    match file.try_lock_exclusive() {
        Ok(()) => {
            let _ = FileExt::unlock(&file);
            false
        }
        Err(error) => matches!(
            error.kind(),
            std::io::ErrorKind::WouldBlock | std::io::ErrorKind::Interrupted
        ),
    }
}

