    #[test]
    fn lexical_rebuild_packet_matches_canonical_and_normalized_semantics_for_host_only_remote() {
        let dir = TempDir::new().unwrap();
        let db_path = dir.path().join("packet-contract.db");
        let storage = FrankenStorage::open(&db_path).unwrap();

        let agent = Agent {
            id: None,
            slug: "codex".into(),
            name: "Codex".into(),
            version: Some("0.2.3".into()),
            kind: AgentKind::Cli,
        };
        let agent_id = storage.ensure_agent(&agent).unwrap();

        let raw_conv = NormalizedConversation {
            agent_slug: "codex".into(),
            external_id: Some("packet-host-only".into()),
            title: Some("Packet host-only remote".into()),
            workspace: Some(PathBuf::from("/tmp/workspace")),
            source_path: PathBuf::from("/tmp/packet-host-only.jsonl"),
            started_at: Some(1_700_000_100_000),
            ended_at: Some(1_700_000_100_100),
            metadata: serde_json::json!({
                "cass": {
                    "origin": {
                        "source_id": "   ",
                        "host": "builder-packet"
                    }
                }
            }),
            messages: vec![
                NormalizedMessage {
                    idx: 0,
                    role: "user".into(),
                    author: Some("user".into()),
                    created_at: Some(1_700_000_100_010),
                    content: "first packet message".into(),
                    extra: serde_json::json!({}),
                    snippets: Vec::new(),
                    invocations: Vec::new(),
                },
                NormalizedMessage {
                    idx: 1,
                    role: "assistant".into(),
                    author: Some("assistant".into()),
                    created_at: Some(1_700_000_100_020),
                    content: "second packet message".into(),
                    extra: serde_json::json!({}),
                    snippets: Vec::new(),
                    invocations: Vec::new(),
                },
            ],
        };

        let canonical = Conversation {
            id: None,
            agent_slug: raw_conv.agent_slug.clone(),
            workspace: raw_conv.workspace.clone(),
            external_id: raw_conv.external_id.clone(),
            title: raw_conv.title.clone(),
            source_path: raw_conv.source_path.clone(),
            started_at: raw_conv.started_at,
            ended_at: raw_conv.ended_at,
            approx_tokens: Some(64),
            metadata_json: raw_conv.metadata.clone(),
            messages: vec![
                Message {
                    id: None,
                    idx: 0,
                    role: MessageRole::User,
                    author: Some("user".into()),
                    created_at: Some(1_700_000_100_010),
                    content: "first packet message".into(),
                    extra_json: serde_json::json!({}),
                    snippets: Vec::new(),
                },
                Message {
                    id: None,
                    idx: 1,
                    role: MessageRole::Agent,
                    author: Some("assistant".into()),
                    created_at: Some(1_700_000_100_020),
                    content: "second packet message".into(),
                    extra_json: serde_json::json!({}),
                    snippets: Vec::new(),
                },
            ],
            source_id: "   ".into(),
            origin_host: Some("builder-packet".into()),
        };

        let workspace_id = storage
            .ensure_workspace(raw_conv.workspace.as_deref().expect("workspace path"), None)
            .unwrap();
        let inserted = storage
            .insert_conversation_tree(agent_id, Some(workspace_id), &canonical)
            .unwrap();
        let (agent_slugs, workspace_paths) = storage.build_lexical_rebuild_lookups().unwrap();
        let replay_row = storage
            .list_conversations_for_lexical_rebuild_after_id(10, 0, &agent_slugs, &workspace_paths)
            .unwrap()
            .into_iter()
            .next()
            .expect("canonical replay row");
        let mut fetched = storage
            .fetch_messages_for_lexical_rebuild_batch(&[inserted.conversation_id], None, None)
            .unwrap();
        let replay_messages = fetched
            .remove(&inserted.conversation_id)
            .expect("canonical replay messages");
        let source_map = storage
            .list_sources()
            .unwrap_or_default()
            .into_iter()
            .map(|source| (source.id, (source.kind, source.host_label)))
            .collect::<HashMap<_, _>>();

        let canonical_packet = LexicalRebuildConversationPacket::from_canonical_replay_messages(
            replay_row,
            replay_messages,
            &source_map,
        )
        .unwrap();
        let normalized_packet =
            LexicalRebuildConversationPacket::from_normalized_conversation(&raw_conv);

        assert_eq!(
            canonical_packet.semantic_view(),
            normalized_packet.semantic_view(),
            "canonical replay and normalized builders should agree on the hot-path semantics"
        );
        assert_eq!(
            canonical_packet.fingerprint_input(),
            normalized_packet.fingerprint_input(),
            "canonical replay and normalized builders should agree on the fingerprint input contract"
        );
        assert_eq!(
            canonical_packet.diagnostics.provenance_mode,
            LexicalRebuildPacketProvenanceMode::SourceMapLookup
        );
        assert_eq!(
            normalized_packet.diagnostics.provenance_mode,
            LexicalRebuildPacketProvenanceMode::HostFallback
        );
    }

    /// Task 2.3 (spec 5.2(c)): the streaming grouped-row lexical rebuild
    /// projection must not collapse 6-role messages to `MessageRole::Agent`,
    /// and `is_tool_role` must recognize `tool_result` (not just the literal
    /// `"tool"` role string) so tool output is correctly classified during
    /// `--force-rebuild`.
    #[test]
    fn lexical_rebuild_grouped_projection_preserves_six_role_and_classifies_tool_result_as_tool() {
        let dir = TempDir::new().unwrap();
        let db_path = dir.path().join("six-role-rebuild.db");
        let storage = FrankenStorage::open(&db_path).unwrap();

        let agent = Agent {
            id: None,
            slug: "codex".into(),
            name: "Codex".into(),
            version: Some("1.0.0".into()),
            kind: AgentKind::Cli,
        };
        let agent_id = storage.ensure_agent(&agent).unwrap();
        let workspace_id = storage
            .ensure_workspace(Path::new("/tmp/six-role-workspace"), None)
            .unwrap();

        let conversation = Conversation {
            id: None,
            agent_slug: "codex".into(),
            workspace: Some(PathBuf::from("/tmp/six-role-workspace")),
            external_id: Some("six-role-rebuild".into()),
            title: Some("Six role rebuild".into()),
            source_path: PathBuf::from("/tmp/six-role-rebuild.jsonl"),
            started_at: Some(1_700_001_000_000),
            ended_at: Some(1_700_001_000_500),
            approx_tokens: None,
            metadata_json: serde_json::Value::Null,
            messages: vec![
                Message {
                    id: None,
                    idx: 0,
                    role: crate::model::types::role_from_str("user"),
                    author: Some("user".into()),
                    created_at: Some(1_700_001_000_010),
                    content: "user turn".into(),
                    extra_json: serde_json::Value::Null,
                    snippets: Vec::new(),
                },
                Message {
                    id: None,
                    idx: 1,
                    role: crate::model::types::role_from_str("assistant"),
                    author: Some("assistant".into()),
                    created_at: Some(1_700_001_000_020),
                    content: "assistant turn".into(),
                    extra_json: serde_json::Value::Null,
                    snippets: Vec::new(),
                },
                Message {
                    id: None,
                    idx: 2,
                    role: crate::model::types::role_from_str("tool_call"),
                    author: Some("assistant".into()),
                    created_at: Some(1_700_001_000_030),
                    content: "tool call turn".into(),
                    extra_json: serde_json::Value::Null,
                    snippets: Vec::new(),
                },
                Message {
                    id: None,
                    idx: 3,
                    role: crate::model::types::role_from_str("tool_result"),
                    author: Some("tool".into()),
                    created_at: Some(1_700_001_000_040),
                    content: "tool result turn".into(),
                    extra_json: serde_json::Value::Null,
                    snippets: Vec::new(),
                },
                Message {
                    id: None,
                    idx: 4,
                    role: crate::model::types::role_from_str("reasoning"),
                    author: None,
                    created_at: Some(1_700_001_000_050),
                    content: "reasoning turn".into(),
                    extra_json: serde_json::Value::Null,
                    snippets: Vec::new(),
                },
            ],
            source_id: LOCAL_SOURCE_ID.into(),
            origin_host: None,
        };

        let inserted = storage
            .insert_conversation_tree(agent_id, Some(workspace_id), &conversation)
            .unwrap();

        // Exercise the real streaming grouped-row rebuild path (the
        // `--force-rebuild` projection) instead of hand-building
        // `LexicalRebuildGroupedMessageRow`s, so the sqlite.rs `is_tool_role`
        // fix is covered end-to-end too.
        let mut grouped_pages: Vec<crate::storage::sqlite::LexicalRebuildGroupedMessageRows> =
            Vec::new();
        storage
            .stream_grouped_messages_for_lexical_rebuild_between_conversation_ids(
                inserted.conversation_id,
                inserted.conversation_id,
                |_conversation_id, messages, _last_message_id| {
                    grouped_pages.push(messages);
                    Ok(())
                },
            )
            .unwrap();
        assert_eq!(
            grouped_pages.len(),
            1,
            "expected exactly one conversation page"
        );
        let grouped_messages = grouped_pages.into_iter().next().unwrap();
        assert_eq!(grouped_messages.len(), 5);

        let tool_result_row = grouped_messages
            .iter()
            .find(|row| row.role == "tool_result")
            .expect("tool_result row present in grouped projection");
        assert!(
            tool_result_row.is_tool_role,
            "is_tool_role must recognize tool_result (not just the literal \"tool\" role)"
        );
        let tool_call_row = grouped_messages
            .iter()
            .find(|row| row.role == "tool_call")
            .expect("tool_call row present in grouped projection");
        assert!(
            !tool_call_row.is_tool_role,
            "tool_call is the assistant-side invocation, not tool output"
        );

        let conversation_row = crate::storage::sqlite::LexicalRebuildConversationRow {
            id: Some(inserted.conversation_id),
            agent_slug: "codex".into(),
            workspace: Some(PathBuf::from("/tmp/six-role-workspace")),
            external_id: Some("six-role-rebuild".into()),
            title: Some("Six role rebuild".into()),
            source_path: PathBuf::from("/tmp/six-role-rebuild.jsonl"),
            started_at: Some(1_700_001_000_000),
            ended_at: Some(1_700_001_000_500),
            source_id: LOCAL_SOURCE_ID.into(),
            origin_host: None,
        };

        let packet = LexicalRebuildConversationPacket::from_canonical_replay(
            conversation_row,
            grouped_messages,
            None,
            &HashMap::new(),
        );

        // The rebuilt packet's roles must not all collapse to `Agent`: the
        // analytics projection must bucket each 6-role message by its own
        // role instead of lumping everything (including `user`!) into the
        // legacy "agent" bucket the old `is_tool_role ? Tool : Agent`
        // mapping produced.
        let analytics = &packet.contract_projections.analytics;
        assert_eq!(
            analytics.user_messages, 1,
            "user must not collapse to agent"
        );
        assert_eq!(analytics.assistant_messages, 1, "assistant stays assistant");
        assert_eq!(
            analytics.tool_messages, 0,
            "tool_call/tool_result are not the literal `tool` role"
        );
        assert_eq!(analytics.system_messages, 0);
        assert_eq!(
            analytics.other_messages, 3,
            "tool_call/tool_result/reasoning round-trip via their own role, not collapsed to agent"
        );

        println!("LEXICAL_6ROLE_OK");
    }

    /// Task 2.3 follow-up: the *live* `--force-rebuild` canonical-replay path
    /// (`fetch_messages_for_lexical_rebuild_batch` -> `from_canonical_replay_messages`,
    /// the sink at `is_tool_role: ...`) must classify a `tool_result`-role
    /// message as tool-class. Before the fix it computed
    /// `matches!(role, MessageRole::Tool)`, which — after the Task 2.1 codec
    /// maps `"tool_result"` to `Other("tool_result")` — is blind to tool
    /// output, so a genuine tool-result acknowledgement ("already up to date")
    /// leaked into the lexical index. This drives the real sink and also
    /// asserts the sink and the `expected_live_lexical_doc_count` counter agree
    /// on the doc count for the same corpus (the cass#244/#258 invariant).
    #[test]
    fn live_force_rebuild_classifies_tool_result_ack_as_tool_and_sink_matches_counter() {
        let dir = TempDir::new().unwrap();
        let db_path = dir.path().join("tool-result-live-rebuild.db");
        let storage = FrankenStorage::open(&db_path).unwrap();

        let agent = Agent {
            id: None,
            slug: "codex".into(),
            name: "Codex".into(),
            version: Some("1.0.0".into()),
            kind: AgentKind::Cli,
        };
        let agent_id = storage.ensure_agent(&agent).unwrap();
        let workspace_id = storage
            .ensure_workspace(Path::new("/tmp/tool-result-live-workspace"), None)
            .unwrap();

        let conversation = Conversation {
            id: None,
            agent_slug: "codex".into(),
            workspace: Some(PathBuf::from("/tmp/tool-result-live-workspace")),
            external_id: Some("tool-result-live-rebuild".into()),
            title: Some("Tool result live rebuild".into()),
            source_path: PathBuf::from("/tmp/tool-result-live-rebuild.jsonl"),
            started_at: Some(1_700_002_000_000),
            ended_at: Some(1_700_002_000_500),
            approx_tokens: None,
            metadata_json: serde_json::Value::Null,
            messages: vec![
                Message {
                    id: None,
                    idx: 0,
                    role: crate::model::types::role_from_str("user"),
                    author: Some("user".into()),
                    created_at: Some(1_700_002_000_010),
                    content: "please refresh the dependency lockfile".into(),
                    extra_json: serde_json::Value::Null,
                    snippets: Vec::new(),
                },
                Message {
                    id: None,
                    idx: 1,
                    role: crate::model::types::role_from_str("assistant"),
                    author: Some("assistant".into()),
                    created_at: Some(1_700_002_000_020),
                    content: "running the refresh now".into(),
                    extra_json: serde_json::Value::Null,
                    snippets: Vec::new(),
                },
                Message {
                    id: None,
                    idx: 2,
                    // "already up to date" is a tool-result acknowledgement that
                    // `is_tool_acknowledgement` drops ONLY when the role is
                    // recognized as tool-class (it carries no "file"/"match"
                    // fallback token). It is the discriminator: pre-fix
                    // is_tool_role=false leaves it in the index; post-fix
                    // is_tool_role=true drops it.
                    role: crate::model::types::role_from_str("tool_result"),
                    author: Some("tool".into()),
                    created_at: Some(1_700_002_000_030),
                    content: "already up to date".into(),
                    extra_json: serde_json::Value::Null,
                    snippets: Vec::new(),
                },
            ],
            source_id: LOCAL_SOURCE_ID.into(),
            origin_host: None,
        };

        let inserted = storage
            .insert_conversation_tree(agent_id, Some(workspace_id), &conversation)
            .unwrap();

        // W2-6 Task丙续: the old canonical-replay `LexicalRebuildConversationPacket`
        // + `prebuilt_docs()` path this test used to drive has no production
        // caller any more (`prepare_lexical_rebuild_packet_batch` /
        // `prepare_lexical_rebuild_packet_from_canonical` are dead -- the real
        // sink is `sync_lexical_domain_for_conversation_in_tx`, which
        // `insert_conversation_tree` above already ran inline). Drive the
        // REAL live sink by reading its DB-domain output (`lex_docs`)
        // directly instead of reconstructing an in-memory packet.

        // (a) RED before / GREEN after: the classifier the sink uses must
        // flag `tool_result` as tool-class (`Other("tool_result")` is not
        // `MessageRole::Tool`, so a naive role-enum match would miss it).
        assert!(
            crate::storage::sqlite::is_lexical_rebuild_tool_class_role("tool_result"),
            "live force-rebuild sink must classify tool_result as tool-class (Other(\"tool_result\") is not MessageRole::Tool)"
        );

        // (b) Behavioral RED before / GREEN after: the tool-result ack must be
        // dropped as hard noise, leaving only the user + assistant docs in
        // lex_docs (DB-domain equivalent of the old in-memory prebuilt_docs()).
        let doc_contents: Vec<String> = storage
            .raw()
            .query_all_map(
                "SELECT content FROM lex_docs WHERE doc_id IN \
                 (SELECT id FROM messages WHERE conversation_id = ?1)",
                &[ParamValue::from(inserted.conversation_id)],
                |row| row.get_typed(0),
            )
            .unwrap();
        assert_eq!(
            doc_contents.len(),
            2,
            "tool_result ack must be dropped from the lexical index, leaving user + assistant"
        );
        assert!(
            !doc_contents.iter().any(|content| content == "already up to date"),
            "the tool_result acknowledgement must not leak into the lexical index"
        );

        // (c) Invariant guard (holds pre- and post-fix, but MUST never
        // diverge): the healthy-doc-count expectation used by the sparse-repair
        // check must agree with what the sink actually emits for this corpus.
        let expected = expected_live_lexical_doc_count(&storage).unwrap();
        assert_eq!(
            expected,
            doc_contents.len(),
            "expected_live_lexical_doc_count (counter) must match lex_docs (sink) for a tool_result corpus"
        );

        println!("LEXICAL_TOOL_RESULT_LIVE_OK");
    }




    #[test]
    fn assign_lexical_rebuild_flow_reservation_bytes_preserves_exact_total() {
        let make_packet = |conversation_id: i64, content: &str| {
            let messages = if content.is_empty() {
                crate::storage::sqlite::LexicalRebuildGroupedMessageRows::new()
            } else {
                vec![crate::storage::sqlite::LexicalRebuildGroupedMessageRow {
                    idx: 0,
                    role: String::new(),
                    is_tool_role: false,
                    created_at: Some(1_700_000_600_000 + conversation_id),
                    content: content.to_string(),
                }]
                .into_iter()
                .collect::<crate::storage::sqlite::LexicalRebuildGroupedMessageRows>()
            };
            LexicalRebuildConversationPacket::from_canonical_replay(
                crate::storage::sqlite::LexicalRebuildConversationRow {
                    id: Some(conversation_id),
                    agent_slug: "codex".into(),
                    workspace: Some(PathBuf::from("/tmp/workspace")),
                    external_id: Some(format!("reservation-{conversation_id}")),
                    title: Some("Reservation packet".into()),
                    source_path: PathBuf::from(format!("/tmp/reservation-{conversation_id}.jsonl")),
                    started_at: Some(1_700_000_600_000),
                    ended_at: Some(1_700_000_600_100),
                    source_id: LOCAL_SOURCE_ID.into(),
                    origin_host: None,
                },
                messages,
                Some(conversation_id),
                &HashMap::new(),
            )
        };

        let mut packets = vec![
            make_packet(1, "abcdefghij"),
            make_packet(2, ""),
            make_packet(3, "0123456789abcdefghij0123456789"),
        ];

        assign_lexical_rebuild_flow_reservation_bytes(&mut packets, 17);

        assert_eq!(
            packets
                .iter()
                .map(|packet| packet.flow_reservation_bytes)
                .sum::<usize>(),
            17
        );
        assert_eq!(packets[1].flow_reservation_bytes, 0);
        assert!(packets[2].flow_reservation_bytes >= packets[0].flow_reservation_bytes);
    }

    #[test]
    fn streaming_batch_flow_reservation_releases_on_drop_and_is_idempotent() {
        let limiter = StreamingByteLimiter::new(16);
        let reserved = limiter.acquire(7).unwrap();
        {
            let _guard = StreamingBatchFlowReservation::new(Some(&limiter), reserved);
            assert_eq!(limiter.bytes_in_flight(), reserved);
        }
        assert_eq!(limiter.bytes_in_flight(), 0);

        let reserved = limiter.acquire(5).unwrap();
        {
            let mut guard = StreamingBatchFlowReservation::new(Some(&limiter), reserved);
            guard.release_now();
            guard.release_now();
        }
        assert_eq!(limiter.bytes_in_flight(), 0);
    }



























    #[test]
    #[serial]
    fn lexical_rebuild_pipeline_settings_snapshot_honors_env_overrides() {
        let _responsiveness = set_env("CASS_RESPONSIVENESS_DISABLE", "1");
        let _workers = set_env("CASS_TANTIVY_REBUILD_WORKERS", "7");
        let _reserved_cores = set_env("CASS_TANTIVY_REBUILD_RESERVED_CORES", "4");
        let _controller_mode = set_env("CASS_TANTIVY_REBUILD_CONTROLLER_MODE", "steady");
        let _controller_clear_samples =
            set_env("CASS_TANTIVY_REBUILD_CONTROLLER_RESTORE_CLEAR_SAMPLES", "5");
        let _controller_hold_ms =
            set_env("CASS_TANTIVY_REBUILD_CONTROLLER_RESTORE_HOLD_MS", "2345");
        let _controller_loadavg_high = set_env(
            "CASS_TANTIVY_REBUILD_CONTROLLER_LOADAVG_HIGH_WATERMARK_1M",
            "7.5",
        );
        let _controller_loadavg_low = set_env(
            "CASS_TANTIVY_REBUILD_CONTROLLER_LOADAVG_LOW_WATERMARK_1M",
            "6.25",
        );
        let _steady_fetch = set_env("CASS_TANTIVY_REBUILD_BATCH_FETCH_CONVERSATIONS", "321");
        let _startup_fetch = set_env(
            "CASS_TANTIVY_REBUILD_INITIAL_BATCH_FETCH_CONVERSATIONS",
            "33",
        );
        let _steady_conversations =
            set_env("CASS_TANTIVY_REBUILD_COMMIT_EVERY_CONVERSATIONS", "654");
        let _startup_conversations = set_env(
            "CASS_TANTIVY_REBUILD_INITIAL_COMMIT_EVERY_CONVERSATIONS",
            "65",
        );
        let _steady_messages = set_env("CASS_TANTIVY_REBUILD_COMMIT_EVERY_MESSAGES", "987");
        let _startup_messages = set_env("CASS_TANTIVY_REBUILD_INITIAL_COMMIT_EVERY_MESSAGES", "98");
        let _steady_message_bytes =
            set_env("CASS_TANTIVY_REBUILD_COMMIT_EVERY_MESSAGE_BYTES", "123456");
        let _startup_message_bytes = set_env(
            "CASS_TANTIVY_REBUILD_INITIAL_COMMIT_EVERY_MESSAGE_BYTES",
            "12345",
        );
        let _pipeline_channel = set_env("CASS_TANTIVY_REBUILD_PIPELINE_CHANNEL_SIZE", "5");
        let _page_prep_workers = set_env("CASS_TANTIVY_REBUILD_PAGE_PREP_WORKERS", "3");
        let _pipeline_bytes = set_env(
            "CASS_TANTIVY_REBUILD_PIPELINE_MAX_MESSAGE_BYTES_IN_FLIGHT",
            "777777",
        );
        let _merge_workers = set_env("CASS_TANTIVY_REBUILD_STAGED_MERGE_WORKERS", "2");

        let snapshot = lexical_rebuild_pipeline_settings_snapshot();

        assert_eq!(snapshot.workers, 7);
        assert!(snapshot.available_parallelism >= 1);
        assert_eq!(
            snapshot.reserved_cores,
            4.min(snapshot.available_parallelism.saturating_sub(1))
        );
        // W2-6 Task丙①: CASS_TANTIVY_MAX_WRITER_THREADS and
        // CASS_TANTIVY_REBUILD_STAGED_SHARD_BUILDERS no longer drive
        // anything (retired, chain-of-custody audit confirmed no live
        // consumer) -- both fields are now fixed at 0 regardless of env.
        assert_eq!(snapshot.tantivy_writer_threads, 0);
        assert_eq!(snapshot.staged_shard_builders, 0);
        assert_eq!(
            snapshot.staged_merge_workers,
            responsiveness::effective_worker_count(2).max(1)
        );
        assert_eq!(snapshot.controller_mode, "steady");
        assert_eq!(snapshot.controller_restore_clear_samples, 5);
        assert_eq!(snapshot.controller_restore_hold_ms, 2345);
        assert_eq!(
            snapshot.controller_loadavg_high_watermark_1m_milli,
            Some(7_500)
        );
        assert_eq!(
            snapshot.controller_loadavg_low_watermark_1m_milli,
            Some(6_250)
        );
        assert_eq!(snapshot.page_size, LEXICAL_REBUILD_PAGE_SIZE);
        assert_eq!(snapshot.steady_batch_fetch_conversations, 321);
        assert_eq!(snapshot.startup_batch_fetch_conversations, 33);
        assert_eq!(snapshot.steady_commit_every_conversations, 654);
        assert_eq!(snapshot.startup_commit_every_conversations, 65);
        assert_eq!(snapshot.steady_commit_every_messages, 987);
        assert_eq!(snapshot.startup_commit_every_messages, 98);
        assert_eq!(snapshot.steady_commit_every_message_bytes, 123456);
        assert_eq!(snapshot.startup_commit_every_message_bytes, 12345);
        assert_eq!(snapshot.pipeline_channel_size, 5);
        assert_eq!(
            snapshot.page_prep_workers,
            responsiveness::effective_worker_count(3).max(1)
        );
        assert_eq!(snapshot.pipeline_max_message_bytes_in_flight, 777777);
    }

    #[test]
