    /// An ACTIVE file-root (recently written) is pre-scan skipped with no
    /// ledger (codex R5): a sibling root's success must not publish the kind
    /// watermark past it. Deterministic in either hash order: the active root
    /// poisons the kind whether it runs before or after the successful root.
    #[test]
    #[serial]
    fn watch_reindex_active_file_root_blocks_sibling_watermark_publication() {
        let tmp = TempDir::new().unwrap();
        let data_dir = tmp.path().join("watch-active-file-root");
        let done_dir = data_dir.join("amp-done");
        let active_dir = data_dir.join("amp-active");
        std::fs::create_dir_all(&done_dir).unwrap();
        std::fs::create_dir_all(&active_dir).unwrap();
        let now = i64::try_from(
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_millis(),
        )
        .unwrap_or(i64::MAX)
        .saturating_add(10_000);

        let done_file = done_dir.join("thread-10-done.json");
        let active_file = active_dir.join("thread-11-active.json");
        std::fs::write(
            &done_file,
            format!(
                r#"{{"id":"thread-10-done","messages":[{{"role":"user","text":"index me","createdAt":{now}}}]}}"#
            ),
        )
        .unwrap();
        std::fs::write(
            &active_file,
            format!(
                r#"{{"id":"thread-11-active","messages":[{{"role":"user","text":"still being written","createdAt":{}}}]}}"#,
                now + 1
            ),
        )
        .unwrap();
        // done_file is cold (mtime 2h ago); active_file keeps its fresh mtime
        // and falls inside the recent-write window below.
        let cold = std::time::SystemTime::now() - std::time::Duration::from_secs(7_200);
        std::fs::OpenOptions::new()
            .write(true)
            .open(&done_file)
            .unwrap()
            .set_modified(cold)
            .unwrap();

        let _window = set_env("CASS_ACTIVE_SESSION_RECENT_WRITE_WINDOW_SECS", "600");
        let opts = super::IndexOptions {
            full: false,
            watch: true,
            force_rebuild: false,
            db_path: data_dir.join("agent_search.db"),
            data_dir: data_dir.clone(),
            semantic: false,
            build_hnsw: false,
            embedder: "fastembed".to_string(),
            progress: None,
            watch_once_paths: None,
            watch_interval_secs: 30,
        };

        let storage = FrankenStorage::open(&opts.db_path).unwrap();
        let state = std::sync::Mutex::new(std::collections::HashMap::new());
        let storage = std::sync::Mutex::new(storage);
        let roots = vec![
            (ConnectorKind::Amp, ScanRoot::local(done_dir)),
            (ConnectorKind::Amp, ScanRoot::local(active_file.clone())),
        ];

        let indexed = reindex_paths(
            &opts,
            vec![done_file, active_file],
            &roots,
            &state,
            &storage,
            false,
        )
        .unwrap();

        assert_eq!(indexed, 1);
        assert!(
            load_watch_state(&data_dir).is_empty(),
            "an active file-root has no ledger, so another root's pending watermark must not publish"
        );
    }

    /// Direct unit coverage for the per-kind publication gate (codex R6 P2),
    /// independent of trigger iteration order: no publish while triggers
    /// remain; a poisoned kind's candidate is consumed unpublished; a clean
    /// sibling kind publishes independently.
    #[test]
    #[serial]
    fn publish_watch_watermark_helper_gates_on_remaining_and_preserve() {
        let tmp = TempDir::new().unwrap();
        let data_dir = tmp.path().to_path_buf();
        let state = std::sync::Mutex::new(std::collections::HashMap::new());
        let mut pending: HashMap<ConnectorKind, i64> = HashMap::new();
        let mut remaining: HashMap<ConnectorKind, usize> = HashMap::new();
        let mut preserve: HashMap<ConnectorKind, bool> = HashMap::new();

        // Triggers remaining: candidate untouched, nothing published.
        pending.insert(ConnectorKind::Amp, 111);
        remaining.insert(ConnectorKind::Amp, 1);
        publish_watch_watermark_if_kind_complete(
            &data_dir,
            &state,
            ConnectorKind::Amp,
            &remaining,
            &mut pending,
            &preserve,
        )
        .unwrap();
        assert_eq!(pending.get(&ConnectorKind::Amp), Some(&111));
        assert!(load_watch_state(&data_dir).is_empty());

        // Kind complete but poisoned: candidate consumed, nothing published.
        remaining.insert(ConnectorKind::Amp, 0);
        preserve.insert(ConnectorKind::Amp, true);
        publish_watch_watermark_if_kind_complete(
            &data_dir,
            &state,
            ConnectorKind::Amp,
            &remaining,
            &mut pending,
            &preserve,
        )
        .unwrap();
        assert!(!pending.contains_key(&ConnectorKind::Amp));
        assert!(load_watch_state(&data_dir).is_empty());

        // A clean sibling kind publishes independently of the poisoned one.
        pending.insert(ConnectorKind::Claude, 222);
        remaining.insert(ConnectorKind::Claude, 0);
        publish_watch_watermark_if_kind_complete(
            &data_dir,
            &state,
            ConnectorKind::Claude,
            &remaining,
            &mut pending,
            &preserve,
        )
        .unwrap();
        let published = load_watch_state(&data_dir);
        assert_eq!(published.get(&ConnectorKind::Claude), Some(&222));
        assert!(!published.contains_key(&ConnectorKind::Amp));
    }

    /// #298 differential: a conversation that OOMs in batch ingest but ingests
    /// cleanly when isolated solo must NOT be quarantined. This is the exact
    /// false-positive the reporter hit — small/medium conversations that index
    /// fine solo were poisoned on the `--watch` batch path.
    #[test]
    #[serial]
    fn watch_batch_oom_that_succeeds_solo_is_not_quarantined() {
        let tmp = TempDir::new().unwrap();
        let xdg = tmp.path().join("xdg_watch_batch_oom_solo_ok");
        std::fs::create_dir_all(&xdg).unwrap();
        let prev = dotenvy::var("XDG_DATA_HOME").ok();
        unsafe { std::env::set_var("XDG_DATA_HOME", &xdg) };

        // Inject a typed OOM on any batch of >= 2 conversations, but leave the
        // solo isolate-retry untouched (it disables injection), so each
        // conversation succeeds when re-ingested alone. Do NOT force the solo
        // retry to OOM — that is the whole point of the differential.
        let _oom_guard = set_env("CASS_TEST_WATCH_INGEST_OOM_MIN_CONVS", "2");
        let _chunk_guard = set_env("CASS_WATCH_INGEST_CHUNK_SIZE", "4");
        let _window_guard = set_env("CASS_ACTIVE_SESSION_RECENT_WRITE_WINDOW_SECS", "0");

        let data_dir = xdg.join("amp");
        std::fs::create_dir_all(&data_dir).unwrap();
        let amp_dir = data_dir.join("amp");
        std::fs::create_dir_all(&amp_dir).unwrap();
        let now_u128 = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_millis();
        let base_ts = i64::try_from(now_u128)
            .unwrap_or(i64::MAX)
            .saturating_add(10_000);
        let mut paths = Vec::new();
        for idx in 0..4 {
            let path = amp_dir.join(format!("thread-batch-oom-solo-ok-{idx}.json"));
            std::fs::write(
                &path,
                format!(
                    r#"{{"id":"thread-batch-oom-solo-ok-{idx}","messages":[{{"role":"user","text":"p{idx}","createdAt":{}}}]}}"#,
                    base_ts + i64::from(idx)
                ),
            )
            .unwrap();
            paths.push(path);
        }

        let progress = Arc::new(super::IndexingProgress::default());
        let opts = super::IndexOptions {
            full: false,
            watch: true,
            force_rebuild: false,
            db_path: data_dir.join("agent_search.db"),
            data_dir: data_dir.clone(),
            semantic: false,
            build_hnsw: false,
            embedder: "fastembed".to_string(),
            progress: Some(progress.clone()),
            watch_once_paths: None,
            watch_interval_secs: 30,
        };

        let storage = FrankenStorage::open(&opts.db_path).unwrap();
        let state = std::sync::Mutex::new(std::collections::HashMap::new());
        let storage = std::sync::Mutex::new(storage);
        let roots = vec![(ConnectorKind::Amp, ScanRoot::local(amp_dir))];

        let indexed = reindex_paths(&opts, paths, &roots, &state, &storage, false).unwrap();

        assert_eq!(indexed, 4);
        assert_eq!(progress.current.load(Ordering::Relaxed), 4);
        let conversation_rows: i64 = storage
            .lock()
            .unwrap()
            .raw()
            .query_row_map(
                "SELECT COUNT(*) FROM conversations",
                &[] as &[ParamValue],
                |row| row.get_typed(0),
            )
            .unwrap();
        assert_eq!(
            conversation_rows, 4,
            "all 4 conversations must persist via the solo isolate-retry"
        );
        assert!(
            !data_dir
                .join("quarantine/watch_ingest_poison.jsonl")
                .exists(),
            "conversations that ingest fine solo must not be quarantined on a batch-path bounded NoMem (#298)"
        );

        if let Some(prev) = prev {
            unsafe { std::env::set_var("XDG_DATA_HOME", prev) };
        } else {
            unsafe { std::env::remove_var("XDG_DATA_HOME") };
        }
    }

    #[test]
    #[serial]
    fn explicit_watch_once_defers_lexical_oom_without_quarantining_source() {
        let tmp = TempDir::new().unwrap();
        let xdg = tmp.path().join("xdg_watch_once_lexical_oom");
        std::fs::create_dir_all(&xdg).unwrap();
        let prev = dotenvy::var("XDG_DATA_HOME").ok();
        unsafe { std::env::set_var("XDG_DATA_HOME", &xdg) };
        let _lexical_oom_guard = set_env("CASS_TEST_INCREMENTAL_LEXICAL_UPDATE_OOM", "1");

        let data_dir = xdg.join("amp");
        std::fs::create_dir_all(&data_dir).unwrap();
        let amp_dir = data_dir.join("amp");
        std::fs::create_dir_all(&amp_dir).unwrap();
        let amp_file = amp_dir.join("thread-watch-once-lexical-oom.json");
        std::fs::write(
            &amp_file,
            r#"{"id":"thread-watch-once-lexical-oom","messages":[{"role":"user","text":"persist me","createdAt":1700000000100}]}"#,
        )
        .unwrap();

        let opts = super::IndexOptions {
            full: false,
            watch: false,
            force_rebuild: false,
            db_path: data_dir.join("agent_search.db"),
            data_dir: data_dir.clone(),
            semantic: false,
            build_hnsw: false,
            embedder: "fastembed".to_string(),
            progress: None,
            watch_once_paths: Some(vec![amp_file.clone()]),
            watch_interval_secs: 30,
        };

        let storage = FrankenStorage::open(&opts.db_path).unwrap();
        let state = std::sync::Mutex::new(std::collections::HashMap::new());
        let storage = std::sync::Mutex::new(storage);
        let roots = vec![(ConnectorKind::Amp, ScanRoot::local(amp_file.clone()))];

        let indexed = reindex_paths(
            &opts,
            vec![amp_file.clone()],
            &roots,
            &state,
            &storage,
            false,
        )
        .unwrap();

        assert_eq!(indexed, 1);
        let (conversation_rows, message_rows): (i64, i64) = {
            let storage = storage.lock().unwrap();
            let conversations = storage
                .raw()
                .query_row_map(
                    "SELECT COUNT(*) FROM conversations",
                    &[] as &[ParamValue],
                    |row| row.get_typed(0),
                )
                .unwrap();
            let messages = storage
                .raw()
                .query_row_map(
                    "SELECT COUNT(*) FROM messages",
                    &[] as &[ParamValue],
                    |row| row.get_typed(0),
                )
                .unwrap();
            (conversations, messages)
        };
        assert_eq!(conversation_rows, 1);
        assert_eq!(message_rows, 1);
        assert!(
            !data_dir
                .join("quarantine/watch_ingest_poison.jsonl")
                .exists(),
            "lexical update OOM must not quarantine a source conversation that persisted to SQLite"
        );
        // W2-6 Task丙续: dropped the tantivy-writer-dropped assertion -- there
        // is no in-memory dirty writer any more in the DB-domain sink
        // (`sync_lexical_domain_for_conversation_in_tx` runs inside the same
        // atomic SQLite transaction as the message insert, so there is no
        // separate "dirty writer" state that can outlive an OOM to begin
        // with). The conversation/message row assertions above already
        // cover the real invariant: SQLite persisted, only the lexical
        // index population was deferred.

        if let Some(prev) = prev {
            unsafe { std::env::set_var("XDG_DATA_HOME", prev) };
        } else {
            unsafe { std::env::remove_var("XDG_DATA_HOME") };
        }
    }

